namespace HanoiGenerated
{
	/** Calls Fn(collection name, row struct) for every content collection. */
	inline void ForEachCollection(TFunctionRef<void(FName, UScriptStruct*)> Fn)
	{
		Fn(FName(TEXT("activities")), FHanoiActivityRow::StaticStruct());
		Fn(FName(TEXT("building_archetypes")), FHanoiBuildingArchetypeRow::StaticStruct());
		Fn(FName(TEXT("businesses")), FHanoiBusinessRow::StaticStruct());
		Fn(FName(TEXT("characters")), FHanoiCharacterRow::StaticStruct());
		Fn(FName(TEXT("dialogues")), FHanoiDialogueRow::StaticStruct());
		Fn(FName(TEXT("districts")), FHanoiDistrictRow::StaticStruct());
		Fn(FName(TEXT("events")), FHanoiEventRow::StaticStruct());
		Fn(FName(TEXT("factions")), FHanoiFactionRow::StaticStruct());
		Fn(FName(TEXT("items")), FHanoiItemRow::StaticStruct());
		Fn(FName(TEXT("landmarks")), FHanoiLandmarkRow::StaticStruct());
		Fn(FName(TEXT("missions")), FHanoiMissionRow::StaticStruct());
		Fn(FName(TEXT("radio")), FHanoiRadioStationRow::StaticStruct());
		Fn(FName(TEXT("random_events")), FHanoiRandomEventsRow::StaticStruct());
		Fn(FName(TEXT("skills")), FHanoiSkillsRow::StaticStruct());
		Fn(FName(TEXT("traffic_rules")), FHanoiTrafficRuleRow::StaticStruct());
		Fn(FName(TEXT("vehicles")), FHanoiVehicleRow::StaticStruct());
	}
}
